def trans(a):
 out=[]
 for name, f in [('id',lambda x:x),('hflip',lambda x:[r[::-1] for r in x]),('vflip',lambda x:x[::-1]),('rot180',lambda x:[r[::-1] for r in x[::-1]]),('transpose',lambda x:[list(r) for r in zip(*x)]),('rot90',lambda x:[list(r) for r in zip(*x[::-1])]),('rot270',lambda x:[list(r) for r in zip(*x)][::-1]),('anti-transpose',lambda x:[list(r) for r in zip(*[r[::-1] for r in x[::-1]])])]:
  y=f(a)
  if y not in [v for _,v in out]: out.append((name,y))
 return out
variants=trans(A)
